ROUTE = '"""routes/poster_tool.py: Poster & Slide Maker page. The editor runs fully in the browser; nothing is stored on the server."""\nfrom flask import render_template\n\nfrom core import login_required\nfrom routes.tools_common import tools_bp\n\n\n@tools_bp.route("/poster-maker")\n@login_required\ndef poster_maker_page():\n    resp = render_template("poster_maker.html")\n    return resp\n'
